/** Real source/replay fixtures; browser/DOM receipts here are typed unit fixtures, not browser evidence. */
public class ObservationTask158Test {
    static JSONObject contract(){return new JSONObject().put("url","http://127.0.0.1:8081/reference").put("checks",new JSONArray().put(new JSONObject().put("selector","h1").put("text","Independent reference")));}
    static JSONObject definition(String id){return new JSONObject().put("profile158",ObservationTask158.KIND).put("evidenceId",id).put("browserContract126",contract()).put("request","Run a verified observation task").put("title","Connected fixture").put("modelName","registered Java procedure").put("saveSkillName","observation-control");}
    static JSONObject[] analytic(){var trace=new JSONArray();var frames=new JSONArray();frames.put(new JSONObject().put("imageSha256","seed"));for(int i=1;i<=5;i++){String hash="image"+i;frames.put(new JSONObject().put("imageSha256",hash));trace.put(new JSONObject().put("ordinal",i).put("imageSha256",hash).put("box",i==3?JSONObject.NULL:new JSONArray("[0.1,0.2,0.3,0.4]")));}return new JSONObject[]{new JSONObject().put("trace",trace),new JSONObject().put("frames",frames)};}
    @Test public void lossBreaksMotionAndUnknownErrorCannotBecomeMetricAuthority(){var a=analytic();var c=ObservationTask158.context(a[0],a[1]);assertEquals(4,c.getInt("accepted"));assertEquals(1,c.getInt("withheld"));assertEquals(2,c.getInt("segments"));assertTrue(c.getJSONArray("rows").getJSONObject(2).isNull("box"));assertEquals(2,c.getJSONArray("rows").getJSONObject(3).getInt("segment"));assertTrue(c.getJSONObject("uncertainty").isNull("positionErrorBound"));assertFalse(c.getJSONObject("uncertainty").getBoolean("metricMapping"));assertFalse(c.getBoolean("physicalActionAuthorized"));}
    @Test public void changedFrameOrderAndExecutableOptionsRefuse(){var a=analytic();a[0].getJSONArray("trace").getJSONObject(1).put("imageSha256","other");assertThrows(IllegalStateException.class,()->ObservationTask158.context(a[0],a[1]));assertThrows(IllegalArgumentException.class,()->ObservationTask158.definition(definition("a".repeat(64)).put("handler","shell")));assertThrows(IllegalArgumentException.class,()->ObservationTask158.definition(definition("a".repeat(64)).put("browserContract126",contract().put("url","file:///private"))));assertEquals("workflow",ChatPolicy044.route("Run a verified observation task",new JSONObject(),false));}
    @Test public void newSnapshotMayLinkOnlyExactOriginalSourcesAndOutcomes(){var a=new JSONObject().put("id","old").put("evidenceFingerprint","old store").put("trace",new JSONArray("[1,2]")).put("datasetSha256","original");var b=WorldFrames.copy(a).put("id","new").put("evidenceFingerprint","new store");ObservationEvidence158.compare(a,b);b.put("trace",new JSONArray("[1,3]"));assertThrows(IllegalStateException.class,()->ObservationEvidence158.compare(a,b));final var wrong=WorldFrames.copy(a).put("datasetSha256","changed");assertThrows(IllegalStateException.class,()->ObservationEvidence158.compare(a,wrong));}
    static final class Harness implements AutoCloseable {
        final Path root;final WorkflowTest.Fixture f;final WorldObservationStore obs;final AssociationAudit134 association;final ContinuityExperiment157 replay;final ObservationTask158 service;
        Harness(Path root)throws Exception{this.root=root;f=new WorkflowTest.Fixture(root);obs=new WorldObservationStore(root,f.goals.worlds());association=new AssociationAudit134(root,obs);replay=new ContinuityExperiment157(root,obs,association,new ReplayEvidence157(root,obs,association));service=new ObservationTask158(root,replay,association,obs,f.goals.worlds());f.workflows.install158(service);}
        String evidence(String audit)throws Exception{return replay.run(audit).getJSONObject("experiment").getString("id");}
        public void close()throws Exception{f.close();replay.close();obs.close();}
    }
    static JSONObject browserHost(JSONObject claim){var contract=claim.getJSONObject("browserContract126");var checks=new JSONArray();for(Object raw:contract.getJSONArray("checks")){var row=(JSONObject)raw;checks.put(new JSONObject().put("selector",row.getString("selector")).put("text",row.getString("text")).put("count",1).put("visible",true));}return new JSONObject().put("schema","browser-outcome-126-v1").put("taskId",claim.getString("workflowId")).put("generation",claim.getInt("generation")).put("effectId",claim.getString("id")).put("contractSha256",WorldFrames.hash(contract)).put("url",contract.getString("url")).put("observedAt",java.time.Instant.now().toString()).put("checks",checks);}
    static String number(double n){return String.format(Locale.ROOT,"%.6f",n);}
    static JSONObject artifactHost(JSONObject a,JSONObject effect){
        var d=new JSONObject(a.getJSONObject("contents").getString("observation.json"));var s=d.getJSONObject("source");var c=s.getJSONObject("context");var world=d.getJSONObject("world");var browser=d.getJSONObject("browser");var rows=c.getJSONArray("rows");var filters=new JSONArray();
        for(String filter:List.of("all","accepted","withheld")){var cells=new JSONArray();for(Object raw:rows){var r=(JSONObject)raw;if(!filter.equals("all")&&r.getBoolean("accepted")!=filter.equals("accepted"))continue;var cell=new JSONArray().put(""+r.getInt("ordinal")).put(r.getString("status")).put(r.isNull("segment")?"—":""+r.getInt("segment"));for(int i=0;i<4;i++)cell.put(r.isNull("box")?"—":number(r.getJSONArray("box").getDouble(i)));cells.put(cell);}filters.put(new JSONObject().put("filter",filter).put("rows",cells));}
        var frames=new JSONArray();for(Object raw:effect.getJSONArray("indexes")){int index=((Number)raw).intValue();var r=rows.getJSONObject(index);var rects=new JSONArray();if(!r.isNull("box")){var b=r.getJSONArray("box");rects.put(new JSONObject().put("x",(double)(float)(b.getDouble(0)*800)).put("y",(double)(float)(b.getDouble(1)*450)).put("width",(double)(float)((b.getDouble(2)-b.getDouble(0))*800)).put("height",(double)(float)((b.getDouble(3)-b.getDouble(1))*450)).put("visible",true));}frames.put(new JSONObject().put("index",index).put("selection","Frame "+r.getInt("ordinal")+" / "+r.getString("status")+" / "+(r.isNull("segment")?"no position":"segment "+r.getInt("segment"))).put("visible",true).put("rectangles",rects));}
        String pos=String.join(", ",world.getJSONArray("worldPosition").toList().stream().map(v->number(((Number)v).doubleValue())).toList());
        var labels=new JSONObject().put("limits",c.getJSONObject("uncertainty").getString("meaning")).put("world","World "+world.getJSONObject("nativeBinding").getString("worldId")+" / revision "+world.getJSONObject("nativeBinding").getInt("expectedRevision")+" / body "+world.getString("bodyId")+". Native position: "+pos+". This is the simulation state, not a measured camera pose.").put("decision","Allowed: "+world.getString("observationUse")+". Physical placement: "+world.getString("physicalPlacement")+". "+world.getString("reason")).put("browser-url",browser.getString("url")).put("source","Evidence "+s.getString("evidenceId")+" / dataset "+s.getString("datasetId")+" / run "+s.getString("runId")+". "+c.getString("clockScope"));
        var refs=new JSONArray();for(Object raw:browser.getJSONArray("checks")){var row=(JSONObject)raw;refs.put(row.getString("selector")+": "+row.getString("text"));}return new JSONObject().put("id",a.getString("id")).put("version",a.getInt("version")).put("filters",filters).put("frames",frames).put("labels",labels).put("browser",refs).put("summary",new JSONArray().put(""+c.getInt("accepted")).put(""+c.getInt("withheld")).put(""+c.getInt("segments")));
    }
    static JSONObject finish(Harness h,String id)throws Exception{var claim=WorkflowTest.driveToAudit(h.f,id);if(claim.getString("kind").equals("workflow.observation-browser158")){WorkflowTest.workflowAck(h.f,claim,browserHost(claim));claim=WorkflowTest.driveToAudit(h.f,id);}WorkflowTest.workflowAck(h.f,claim,artifactHost(h.f.artifacts.read(claim.getJSONObject("report").getString("id")),claim));var done=WorkflowTest.completed(h.f,id);assertEquals(done.toString(),"completed",done.getString("status"));return done;}
    @Test public void originalReplayToWorldBrowserArtifactAndRetainedLifecycle()throws Exception{
        try(var seed=new StartingReference150Test.Fixture();var h=new Harness(seed.root)){
            String evidence=h.evidence(seed.audit.getString("id"));var before=h.f.goals.worlds().observe(seed.world);var w=h.f.workflows.start(definition(evidence));var done=finish(h,w.getString("id"));assertTrue(before.similar(h.f.goals.worlds().observe(seed.world)));assertEquals("refused",done.getJSONObject("world158").getString("physicalPlacement"));assertTrue(done.getJSONArray("revalidations158").length()>0);
            var lineage=done.getJSONArray("revalidations158").getJSONObject(0);Path lineageFile=seed.root.resolve("observation-revalidations158/"+lineage.getString("id")+".json");String originalLineage=Files.readString(lineageFile);Files.writeString(lineageFile,new JSONObject(originalLineage).put("originalFingerprint","changed").toString());assertThrows(Exception.class,()->h.f.workflows.verifyArchive110(done.getString("id")));Files.writeString(lineageFile,originalLineage);
            var skill=done.getJSONObject("savedSkill");assertTrue(h.f.workflows.verifyArchive110(done.getString("id")).getBoolean("passed"));assertTrue(h.f.workflows.inspectProcedure127(new JSONObject().put("id",skill.getString("id"))).getJSONObject("evidence").getBoolean("passed"));
            // Add a separately named label record: full store fingerprint changes, original trace does not.
            var labels=WorldFrames.copy(seed.labels).put("provenance","Fresh separately selected fixture labels");var audit=seed.audit(seed.association.save(labels));String fresh=h.evidence(audit.getString("id"));
            var reuse=new JSONObject().put("name",skill.getString("name")).put("version",skill.getInt("version")).put("evidenceId",fresh).put("browserContract126",contract());var next=h.f.workflows.reuse(reuse);var second=finish(h,next.getString("id"));assertNotEquals(done.getJSONObject("observation158").getString("evidenceId"),second.getJSONObject("observation158").getString("evidenceId"));
            ProcedureLifecycle127Test.change(h.f,skill,"retire");assertThrows(IllegalStateException.class,()->h.f.workflows.reuse(reuse));ProcedureLifecycle127Test.passed(ProcedureLifecycle127Test.change(h.f,skill,"reactivate"));
            var a=h.f.artifacts.read(done.getJSONObject("report").getString("id"));h.f.artifacts.write(new JSONObject().put("id",a.getString("id")).put("expectedVersion",1).put("title","Tampered").put("files",new JSONObject().put("index.html","<body>changed</body>")));assertFalse(h.f.workflows.inspectProcedure127(new JSONObject().put("id",skill.getString("id"))).getJSONObject("evidence").getBoolean("passed"));
        }
    }
    @Test public void restartRechecksSameSourceAndRejectsStaleBrowserClaim()throws Exception{
        try(var seed=new StartingReference150Test.Fixture()){
            JSONObject saved,claim;try(var h=new Harness(seed.root)){var in=definition(h.evidence(seed.audit.getString("id"))).put("reviewAfterWorld158",true);saved=h.f.workflows.start(in);saved=WorkflowTest.completed(h.f,saved.getString("id"));assertEquals("interrupted",saved.getString("status"));h.f.workflows.resume(saved.getString("id"));claim=WorkflowTest.driveToAudit(h.f,saved.getString("id"));}
            try(var h=new Harness(seed.root)){var resumed=h.f.workflows.resume(saved.getString("id"));assertTrue(saved.getJSONObject("world158").similar(resumed.getJSONObject("world158")));assertThrows(IllegalStateException.class,()->WorkflowTest.workflowAck(h.f,claim,browserHost(claim)));finish(h,saved.getString("id"));}
        }
    }
    @Test public void changedBrowserAndForgedVisibleUncertaintyCannotComplete()throws Exception{
        try(var seed=new StartingReference150Test.Fixture();var h=new Harness(seed.root)){
            var w=h.f.workflows.start(definition(h.evidence(seed.audit.getString("id"))));var claim=WorkflowTest.driveToAudit(h.f,w.getString("id"));var wrong=browserHost(claim);wrong.getJSONArray("checks").getJSONObject(0).put("text","wrong reference");assertEquals("interrupted",WorkflowTest.workflowAck(h.f,claim,wrong).getString("status"));assertEquals(0,h.f.goals.procedures().length());
            h.f.workflows.resume(w.getString("id"));claim=WorkflowTest.driveToAudit(h.f,w.getString("id"));WorkflowTest.workflowAck(h.f,claim,browserHost(claim));claim=WorkflowTest.driveToAudit(h.f,w.getString("id"));var actual=artifactHost(h.f.artifacts.read(claim.getJSONObject("report").getString("id")),claim);actual.getJSONObject("labels").put("limits","Accurate physical position");assertEquals("interrupted",WorkflowTest.workflowAck(h.f,claim,actual).getString("status"));assertEquals(0,h.f.goals.procedures().length());
            h.f.workflows.resume(w.getString("id"));finish(h,w.getString("id"));
        }
    }
    @Test public void changedSourceOrWorldRefusesWithoutReplacingEvidence()throws Exception{
        try(var seed=new StartingReference150Test.Fixture();var h=new Harness(seed.root)){
            var in=definition(h.evidence(seed.audit.getString("id"))).put("reviewAfterWorld158",true);var w=h.f.workflows.start(in);w=WorkflowTest.completed(h.f,w.getString("id"));final String id=w.getString("id");var binding=w.getJSONObject("observation158").getJSONObject("nativeBinding");h.f.goals.worlds().restore(seed.world,binding.getInt("expectedRevision"),binding.getString("expectedHash"),binding.getInt("expectedRevision"),"");assertThrows(IllegalStateException.class,()->h.f.workflows.resume(id));h.f.workflows.cancel(id);
            Path image=seed.root.resolve("world-observations/datasets/"+seed.data.getString("id")+"/2.image");var original=Files.readAllBytes(image);var time=Files.getLastModifiedTime(image);var changed=original.clone();changed[changed.length/2]^=1;Files.write(image,changed);Files.setLastModifiedTime(image,time);assertThrows(Exception.class,()->h.f.workflows.start(in));assertFalse(h.f.goals.workflowReserved());Files.write(image,original);Files.setLastModifiedTime(image,time);
        }
    }
}
